/// MATRIX Connect — QR pairing screen.
///
/// Scans a `matrix-pairing:v1.…` payload generated by the web dashboard and
/// completes pairing via POST /api/devices/pairing/complete. The QR contains
/// no credentials; the server verifies signature, expiry and one-time use.
library;

import 'package:flutter/material.dart';
import 'package:mobile_scanner/mobile_scanner.dart';
import 'api.dart';

class PairingScreen extends StatefulWidget {
  const PairingScreen({super.key, required this.api});
  final MatrixApi api;
  @override
  State<PairingScreen> createState() => _PairingScreenState();
}

class _PairingScreenState extends State<PairingScreen> {
  bool _busy = false;
  String? _message;
  bool _done = false;
  final _controller = MobileScannerController();

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  Future<void> _onDetect(BarcodeCapture capture) async {
    if (_busy || _done) return;
    final raw = capture.barcodes.isNotEmpty ? capture.barcodes.first.rawValue : null;
    if (raw == null || !raw.startsWith('matrix-pairing:v1.')) return;
    setState(() { _busy = true; _message = null; });
    await _controller.stop();
    try {
      final deviceName = 'Android phone (${DateTime.now().toIso8601String().substring(0, 10)})';
      final res = await widget.api.postJson('/api/devices/pairing/complete', {
        'qr_payload': raw,
        'device_name': deviceName,
        'device_type': 'phone',
        'platform': 'android',
      });
      setState(() {
        _done = true;
        _message = 'Linked: ${(res['device'] as Map?)?['device_name'] ?? 'device'}';
      });
    } on ApiException catch (e) {
      setState(() => _message = 'Pairing failed: ${e.code.replaceAll('_', ' ').toLowerCase()}');
      await _controller.start();
    } finally {
      setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Pair this device')),
      body: Column(
        children: [
          Expanded(
            child: _done
                ? Center(child: Column(mainAxisSize: MainAxisSize.min, children: [
                    const Icon(Icons.check_circle, color: Colors.green, size: 56),
                    const SizedBox(height: 12),
                    Text(_message ?? 'Paired', textAlign: TextAlign.center),
                  ]))
                : MobileScanner(controller: _controller, onDetect: _onDetect),
          ),
          Padding(
            padding: const EdgeInsets.all(16),
            child: Text(
              _message ?? 'Scan the QR shown in MATRIX → Devices → “Add a device”. The code expires in 5 minutes and works once.',
              textAlign: TextAlign.center,
              style: const TextStyle(color: Colors.grey),
            ),
          ),
        ],
      ),
    );
  }
}
